import React, { useState } from "react";
import ComplaintRow from "./ComplaintRow";
import ComplaintDetailsModal from "./ComplaintDetailsModal";
import "./ComplaintTable.css";

// Sample complaint records for the table (would come from the backend API)
const sampleComplaints = [
  {
    id: "CMP-1001",
    citizenName: "Rohit Sharma",
    issue: "Garbage not collected",
    department: "Sanitation",
    priority: "High",
    status: "Pending",
    submittedOn: "22 Jul 2026",
    description: "Garbage has not been collected from our street for 4 days.",
  },
  {
    id: "CMP-1002",
    citizenName: "Anita Desai",
    issue: "Streetlight not working",
    department: "Electricity",
    priority: "Medium",
    status: "In Progress",
    submittedOn: "21 Jul 2026",
    description: "The streetlight near the park entrance has been off for a week.",
  },
  {
    id: "CMP-1003",
    citizenName: "Suresh Kumar",
    issue: "Water leakage",
    department: "Water Supply",
    priority: "High",
    status: "Resolved",
    submittedOn: "18 Jul 2026",
    description: "Pipeline leakage was fixed by the water department team.",
  },
];

// Uses useState and map() to dynamically display complaint records
// and opens a reusable modal to view complaint details.
function ComplaintTable() {
  const [complaints] = useState(sampleComplaints);
  const [selectedComplaint, setSelectedComplaint] = useState(null);

  return (
    <div className="complaint-table-container">
      <div className="complaint-table-header">
        <h3>Complaint Management</h3>
        <span className="complaint-table-count">{complaints.length} records</span>
      </div>
      <table className="complaint-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Citizen</th>
            <th>Issue</th>
            <th>Department</th>
            <th>Priority</th>
            <th>Status</th>
            <th>Action</th>
          </tr>
        </thead>
        <tbody>
          {complaints.map((complaint) => (
            <ComplaintRow
              key={complaint.id}
              complaint={complaint}
              onView={setSelectedComplaint}
            />
          ))}
        </tbody>
      </table>

      <ComplaintDetailsModal
        complaint={selectedComplaint}
        onClose={() => setSelectedComplaint(null)}
      />
    </div>
  );
}

export default ComplaintTable;
